#[derive(Debug, thiserror::Error)]
pub enum DeterministicJsonError {
  #[error("codegen API call failed: {0}")]
  Codegen(LlmError),

  #[error("anchor-picker API call failed: {0}")]
  AnchorPicker(LlmError),

  #[error("codegen output was truncated; raise CODEGEN_MAX_TOKENS")]
  Truncated,

  #[error("extractor failed validation after retry:\n{0}")]
  Validation(String),

  /// The sandbox's own message, or the client's timeout and connection errors.
  #[error("{0}")]
  Sandbox(String),

  #[error("{0}")]
  AskLlm(String),

  #[error("{0} is not configured.")]
  NotConfigured(&'static str),

  #[error(transparent)]
  Cache(#[from] sqlx::Error),
}

/// TS `sha`: the first 32 hex chars of the SHA-256.
fn sha(input: &str) -> String {
  let mut hex = hex::encode(Sha256::digest(input.as_bytes()));
  hex.truncate(32);
  hex
}

/// TS `performDeterministicJson`. Failures become a warning, never an error.
#[instrument(
  name = "transformers::deterministic_json::perform_deterministic_json",
  skip(meta, document),
  fields(outcome = Empty),
  err
)]
pub async fn perform_deterministic_json(
  meta: &Meta,
  mut document: Document,
) -> Result<Document, TransformerError> {
  let Some(options) = meta.options.formats.deterministic_json() else {
    return Ok(document);
  };
  let span = Span::current();

  if meta.internal_options.zero_data_retention {
    span.record("outcome", "zero_data_retention");
    document.prepend_warning("Deterministic JSON mode is not supported with zero data retention.");
    return Ok(document);
  }

  let html = document
    .html
    .as_deref()
    .or(document.raw_html.as_deref())
    .filter(|x| !x.is_empty());
  let Some(html) = html else {
    span.record("outcome", "no_html");
    document.prepend_warning("Deterministic JSON mode requires page HTML.");
    return Ok(document);
  };

  let empty_schema = Value::Object(Default::default());
  let result = extract_deterministic_json(ExtractArgs {
    url: &document.metadata.source_url,
    prompt: options.prompt.as_deref().unwrap_or_default(),
    json_schema: options.schema.as_ref().unwrap_or(&empty_schema),
    html,
    markdown: document.markdown.as_deref().unwrap_or_default(),
    cost_tracking: &meta.cost_tracking,
  })
  .await;

  match result {
    Ok(json) => {
      span.record("outcome", "extracted");
      document.json = json;
    }
    Err(_) => {
      span.record("outcome", "failed");
      document.prepend_warning("Deterministic JSON extraction failed.");
    }
  }
  Ok(document)
}
